use std::ptr;
use std::alloc::{self, Layout};

impl SmallVecU64 {
    pub fn append(&mut self, val: u64) {
        unsafe {
            if self.n < 16 {
                self.buf[self.n] = val;
                self.n += 1;
                return;
            }
            if self.n == 16 {
                self.capacity = 2 * 16;
                let layout = Layout::array::<u64>(self.capacity).unwrap();
                self.p = alloc::alloc(layout) as *mut u64;
                if self.p.is_null() {
                    std::process::exit(1);
                }
                ptr::copy_nonoverlapping(self.buf.as_ptr(), self.p, 16);
            } else if self.n == self.capacity {
                self.capacity *= 2;
                let layout = Layout::array::<u64>(self.capacity).unwrap();
                let new_p = alloc::realloc(self.p as *mut u8, layout, self.capacity * std::mem::size_of::<u64>()) as *mut u64;
                if new_p.is_null() {
                    std::process::exit(1);
                }
                self.p = new_p;
            }
            *self.p.add(self.n) = val;
            self.n += 1;
        }
    }
}

