pub fn parse_ld_config_file(st: &mut StringTable, path: &str) -> io::Result<i32> {
    let file = File::open(path)?;
    let reader = BufReader::new(file);
    let mut tmp = String::with_capacity(4096);

    for line in reader.lines() {
        let mut line = line?;
        let mut begin = line.trim_start();
        if let Some(comment_pos) = begin.find('#') {
            begin = &begin[..comment_pos];
        }
        let end = begin.trim_end();
        if begin.is_empty() {
            continue;
        }

        if end.starts_with("include") && end[7..].chars().next().map_or(false, |c| c.is_whitespace()) {
            let mut include_path = end[8..].trim_start();
            if !include_path.starts_with('/') {
                if let Some(wd) = Path::new(path).parent() {
                    let mut wd_buf = wd.to_path_buf();
                    wd_buf.push(include_path);
                    tmp = wd_buf.to_string_lossy().into_owned();
                    include_path = &tmp;
                }
            }
            ld_conf_globbing(st, include_path)?;
        } else {
            string_table_store(st, end);
            if let Some(last) = st.arr.last_mut() {
                *last = b':';
            }
        }
    }
    Ok(0)
}

pub fn ld_conf_globbing(st: &mut StringTable, pattern: &str) -> io::Result<i32> {
    let mut code = 0;
    for entry in glob(pattern)? {
        match entry {
            Ok(path) => {
                if let Some(path_str) = path.to_str() {
                    code |= parse_ld_config_file(st, path_str)?;
                }
            }
            Err(_) => return Ok(1),
        }
    }
    Ok(code)
}

