pub fn apply_exclude_list(
    needed_not_found: &mut usize,
    needed_buf_offsets: &mut SmallVecU64,
    s: &LibtreeState,
) {
    let mut i = 0;
    while i < *needed_not_found {
        let offset = unsafe { *needed_buf_offsets.p.add(i) };
        let soname = &s.string_table.arr[offset as usize..];
        if let Some(null_pos) = soname.iter().position(|&c| c == 0) {
            let soname_str = std::str::from_utf8(&soname[..null_pos]).unwrap_or("");
            if is_in_exclude_list(soname_str) {
                let tmp = unsafe { *needed_buf_offsets.p.add(i) };
                unsafe {
                    *needed_buf_offsets.p.add(i) =
                        *needed_buf_offsets.p.add(*needed_not_found - 1);
                    *needed_buf_offsets.p.add(*needed_not_found - 1) = tmp;
                }
                *needed_not_found -= 1;
                continue;
            }
        }
        i += 1;
    }
}

use std::str;

pub fn interpolate_variables(
    s: &mut LibtreeState,
    src: usize,
    origin: &str,
) -> i32 {
    let mut prev_src = src;
    let mut curr_src = src;
    let st = &mut s.string_table;

    loop {
        let dollar_pos = st.arr[curr_src..].iter().position(|&c| c == b'$');
        if dollar_pos.is_none() {
            break;
        }
        curr_src += dollar_pos.unwrap();
        let bytes_to_dollar = curr_src - prev_src;
        curr_src += 1;

        let mut curly = false;
        if st.arr[curr_src] == b'{' {
            curly = true;
            curr_src += 1;
        }

        let mut var_val: Option<&str> = None;
        if st.arr[curr_src..].starts_with(b"ORIGIN") {
            var_val = Some(origin);
            curr_src += 6;
        } else if st.arr[curr_src..].starts_with(b"LIB") {
            var_val = s.lib.as_deref();
            curr_src += 3;
        } else if st.arr[curr_src..].starts_with(b"PLATFORM") {
            var_val = s.platform.as_deref();
            curr_src += 8;
        } else if st.arr[curr_src..].starts_with(b"OSNAME") {
            var_val = s.osname.as_deref();
            curr_src += 6;
        } else if st.arr[curr_src..].starts_with(b"OSREL") {
            var_val = s.osrel.as_deref();
            curr_src += 5;
        } else {
            continue;
        }

        if curly {
            if st.arr[curr_src] != b'}' {
                continue;
            }
            curr_src += 1;
        }

        if let Some(var_val) = var_val {
            let var_len = var_val.len();
            string_table_maybe_grow(st, bytes_to_dollar + var_len);

            st.arr.splice(
                st.n..st.n + bytes_to_dollar,
                st.arr[prev_src..prev_src + bytes_to_dollar].iter().cloned(),
            );
            st.n += bytes_to_dollar;

            st.arr.splice(
                st.n..st.n + var_len,
                var_val.as_bytes().iter().cloned(),
            );
            st.n += var_len;

            prev_src = curr_src;
        }
    }

    if prev_src != src {
        let remaining_len = st.arr[prev_src..].len();
        string_table_maybe_grow(st, remaining_len);

        st.arr.splice(
            st.n..st.n + remaining_len,
            st.arr[prev_src..].iter().cloned(),
        );
        st.n += remaining_len;

        return 1;
    }

    0
}

