    s.ld_so_conf_offset = st.n;
    if let Some(ld_conf_file) = &s.ld_conf_file {
        parse_ld_config_file(st, ld_conf_file).unwrap_or_else(|_| {});
    }
    if st.n > s.ld_so_conf_offset {
        if let Some(last) = st.arr.last_mut() {
            *last = b'\0';
        }
    } else {
        string_table_store(st, "");
    }
}

pub fn print_line(
    depth: usize,
    name: &str,
    color_bold: &str,
    color_regular: &str,
    highlight: bool,
    reason: Found,
    s: &LibtreeState,
) {
    tree_preamble(s, depth);

    let mut slash: Option<&str> = None;
    if s.color != 0 && highlight {
        slash = name.rfind('/').map(|pos| &name[pos..]);
    }

    if let Some(slash) = slash {
        io::stdout().write_all(color_regular.as_bytes()).unwrap();
        io::stdout()
            .write_all(&name.as_bytes()[..name.len() - slash.len()])
            .unwrap();
        io::stdout().write_all(color_bold.as_bytes()).unwrap();
        io::stdout().write_all(slash.as_bytes()).unwrap();
    } else {
        if s.color != 0 {
            io::stdout().write_all(color_bold.as_bytes()).unwrap();
        }
        io::stdout().write_all(name.as_bytes()).unwrap();
    }

    if s.color != 0 && highlight {
        io::stdout().write_all(b"\x1b[0m \x1b[33m").unwrap();
    } else {
        io::stdout().write_all(b" ").unwrap();
    }

    match reason.how {
        How::Rpath => {
            if reason.depth + 1 >= depth {
                io::stdout().write_all(b"[rpath]").unwrap();
            } else {
                let mut num = [0u8; 8];
                utoa(&mut num, reason.depth + 1);
                io::stdout().write_all(b"[rpath of ").unwrap();
                io::stdout().write_all(&num).unwrap();
                io::stdout().write_all(b"]").unwrap();
            }
        }
        How::LdLibraryPath => {
            io::stdout().write_all(b"[LD_LIBRARY_PATH]").unwrap();
        }
        How::Runpath => {
            io::stdout().write_all(b"[runpath]").unwrap();
        }
        How::LdSoConf => {
            io::stdout().write_all(b"[").unwrap();
            if let Some(conf_name) = s.ld_conf_file.as_ref().and_then(|file| file.rfind('/').map(|pos| &file[pos + 1..])) {
                io::stdout().write_all(conf_name.as_bytes()).unwrap();
            } else if let Some(conf_name) = &s.ld_conf_file {
                io::stdout().write_all(conf_name.as_bytes()).unwrap();
            }
            io::stdout().write_all(b"]").unwrap();
        }
        How::Direct => {
            io::stdout().write_all(b"[direct]").unwrap();
        }
        How::Default => {
            io::stdout().write_all(b"[default path]").unwrap();
        }
        _ => {}
    }

    if s.color != 0 {
        io::stdout().write_all(b"\x1b[0m\n").unwrap();
    } else {
        io::stdout().write_all(b"\n").unwrap();
    }
}

pub fn print_error(
    depth: usize,
    needed_not_found: usize,
    needed_buf_offsets: &SmallVecU64,
    runpath: Option<&str>,
    s: &mut LibtreeState,
    no_def_lib: bool,
) {
    for i in 0..needed_not_found {
        s.found_all_needed[depth] = i + 1 >= needed_not_found;
        tree_preamble(s, depth + 1);
        if s.color {
            print!("\x1b[1;31m");
        }
        let offset = needed_buf_offsets.p[i] as usize;
        let name = &s.string_table.arr[offset..];
        print!("{} not found\n", String::from_utf8_lossy(name));
        if s.color {
            print!("\x1b[0m");
        }
    }

    let box_vertical = if s.color {
        "    \x1b[0;31m\u{250a}\x1b[0m"
    } else {
        "    \u{250a}"
    };

    let indent_size = depth * "│   ".len() + box_vertical.len();
    let mut indent = String::with_capacity(indent_size);

    for i in 0..depth {
        if s.found_all_needed[i] != 0 {
            indent.push_str("    ");
        } else {
            indent.push_str("│   ");
        }
    }
    indent.push_str(box_vertical);

    print!("{}", indent);
    if s.color {
        print!("\x1b[0;90m");
    }
    print!(" Paths considered in this order:\n");
    if s.color {
        print!("\x1b[0m");
    }

    print!("{}", indent);
    if let Some(runpath) = runpath {
        if s.color {
            print!("\x1b[0;90m");
        }
        print!(" 1. rpath is skipped because runpath was set\n");
        if s.color {
            print!("\x1b[0m");
        }
    } else {
        if s.color {
            print!("\x1b[0;90m");
        }
        print!(" 1. rpath:\n");
        if s.color {
            print!("\x1b[0m");
        }
        for j in (0..=depth).rev() {
            if s.rpath_offsets[j] != usize::MAX {
                let num = (j + 1).to_string();
                print!("{}", indent);
                if s.color {
                    print!("\x1b[0;90m");
                }
                print!("    depth {}", num);
                if s.color {
                    print!("\x1b[0m");
                }
                println!();
                print_colon_delimited_paths(
                    &s.string_table.arr[s.rpath_offsets[j]..],
                    &indent,
                );
            }
        }
    }

    print!("{}", indent);
    if s.color {
        print!("\x1b[0;90m");
    }
    if s.ld_library_path_offset == usize::MAX {
        print!(" 2. LD_LIBRARY_PATH was not set\n");
    } else {
        print!(" 2. LD_LIBRARY_PATH:\n");
        print_colon_delimited_paths(
            &s.string_table.arr[s.ld_library_path_offset..],
            &indent,
        );
    }
    if s.color {
        print!("\x1b[0m");
    }

    print!("{}", indent);
    if s.color {
        print!("\x1b[0;90m");
    }
    if runpath.is_none() {
        print!(" 3. runpath was not set\n");
    } else {
        print!(" 3. runpath:\n");
        print_colon_delimited_paths(runpath.unwrap(), &indent);
    }
    if s.color {
        print!("\x1b[0m");
    }

    print!("{}", indent);
    if s.color {
        print!("\x1b[0;90m");
    }
    if no_def_lib {
        print!(" 4. ld config files not considered due to NODEFLIB flag\n");
    } else {
        print!(" 4. ld config files:\n");
        print_colon_delimited_paths(
            &s.string_table.arr[s.ld_so_conf_offset..],
            &indent,
        );
    }
    if s.color {
        print!("\x1b[0m");
    }

    print!("{}", indent);
    if s.color {
        print!("\x1b[0;90m");
    }
    if no_def_lib {
        print!(" 5. Standard paths not considered due to NODEFLIB flag\n");
    } else {
        print!(" 5. Standard paths:\n");
        print_colon_delimited_paths(
            &s.string_table.arr[s.default_paths_offset..],
            &indent,
        );
    }
    if s.color {
        print!("\x1b[0m");
    }
}

use std::fs::File;
use std::io::{self, Read, Seek, SeekFrom};
use std::os::raw::c_char;
use std::path::Path;

pub fn recurse(
    current_file: &str,
    depth: usize,
    s: &mut LibtreeState,
    compat: CompatT,
    reason: Found,
) -> i32 {
    let mut fptr = match File::open(current_file) {
        Ok(file) => file,
        Err(_) => return 31,
    };

    let old_buf_size = s.string_table.n;
    let mut e_ident = [0u8; 16];
    if fptr.read_exact(&mut e_ident).is_err() {
        return 11;
    }

    if e_ident[0] != 0x7f || e_ident[1] != b'E' || e_ident[2] != b'L' || e_ident[3] != b'F' {
        return 11;
    }

    if e_ident[4] != 1 && e_ident[4] != 2 {
        return 12;
    }

    if e_ident[5] != 0x01 && e_ident[5] != 0x02 {
        return 13;
    }

    let curr_type = CompatT {
        any: 0,
        class: e_ident[4],
        machine: 0,
    };
    let is_little_endian = e_ident[5] == 0x01;

    if compat.any == 0 && compat.class != curr_type.class {
        return 15;
    }

    if is_little_endian ^ host_is_little_endian() {
        return 16;
    }

    let mut header = if curr_type.class == 2 {
        let mut h64 = Header64::default();
        if fptr.read_exact(bytemuck::bytes_of_mut(&mut h64)).is_err() {
            return 14;
        }
        if h64.e_type != 2 && h64.e_type != 3 {
            return 17;
        }
        curr_type.machine = h64.e_machine;
        if compat.any == 0 && compat.machine != curr_type.machine {
            return 32;
        }
        if fptr.seek(SeekFrom::Start(h64.e_phoff as u64)).is_err() {
            return 18;
        }
        Header::Header64(h64)
    } else {
        let mut h32 = Header32::default();
        if fptr.read_exact(bytemuck::bytes_of_mut(&mut h32)).is_err() {
            return 14;
        }
        if h32.e_type != 2 && h32.e_type != 3 {
            return 17;
        }
        curr_type.machine = h32.e_machine;
        if compat.any == 0 && compat.machine != curr_type.machine {
            return 32;
        }
        if fptr.seek(SeekFrom::Start(h32.e_phoff as u64)).is_err() {
            return 18;
        }
        Header::Header32(h32)
    };

    let mut pt_load_offset = SmallVecU64::new();
    let mut pt_load_vaddr = SmallVecU64::new();
    let mut p_offset = u64::MAX;

    match header {
        Header::Header64(ref h64) => {
            for _ in 0..h64.e_phnum {
                let mut p64 = Prog64::default();
                if fptr.read_exact(bytemuck::bytes_of_mut(&mut p64)).is_err() {
                    return 19;
                }
                match p64.p_type {
                    1 => {
                        pt_load_offset.append(p64.p_offset);
                        pt_load_vaddr.append(p64.p_vaddr);
                    }
                    2 => p_offset = p64.p_offset,
                    _ => {}
                }
            }
        }
        Header::Header32(ref h32) => {
            for _ in 0..h32.e_phnum {
                let mut p32 = Prog32::default();
                if fptr.read_exact(bytemuck::bytes_of_mut(&mut p32)).is_err() {
                    return 19;
                }
                match p32.p_type {
                    1 => {
                        pt_load_offset.append(p32.p_offset as u64);
                        pt_load_vaddr.append(p32.p_vaddr as u64);
                    }
                    2 => p_offset = p32.p_offset as u64,
                    _ => {}
                }
            }
        }
    }

    let finfo = match std::fs::metadata(current_file) {
        Ok(metadata) => metadata,
        Err(_) => return 20,
    };

    let seen_before = visited_files_contains(&s.visited, &finfo);
    if !seen_before {
        visited_files_append(&mut s.visited, &finfo);
    }

    if p_offset == u64::MAX {
        print_line(depth, current_file, "\x1b[1;36m", "\x1b[0;36m", true, reason, s);
        return 0;
    }

    if pt_load_offset.is_empty() {
        return 29;
    }

    if fptr.seek(SeekFrom::Start(p_offset)).is_err() {
        return 21;
    }

    let mut no_def_lib = false;
    let mut strtab = u64::MAX;
    let mut rpath = u64::MAX;
    let mut runpath = u64::MAX;
    let mut soname = u64::MAX;
    let mut needed = SmallVecU64::new();

    loop {
        let (d_tag, d_val) = if curr_type.class == 2 {
            let mut dyn64 = Dyn64::default();
            if fptr.read_exact(bytemuck::bytes_of_mut(&mut dyn64)).is_err() {
                return 22;
            }
            (dyn64.d_tag as u64, dyn64.d_val)
        } else {
            let mut dyn32 = Dyn32::default();
            if fptr.read_exact(bytemuck::bytes_of_mut(&mut dyn32)).is_err() {
                return 22;
            }
            (dyn32.d_tag as u64, dyn32.d_val as u64)
        };

        match d_tag {
            0 => break,
            5 => strtab = d_val,
            15 => rpath = d_val,
            29 => runpath = d_val,
            1 => needed.append(d_val),
            14 => soname = d_val,
            0x6ffffffb => no_def_lib |= (0x800 & d_val) == 0x800,
            _ => {}
        }
    }

    if strtab == u64::MAX {
        return 23;
    }

    if !is_ascending_order(&pt_load_vaddr) {
        return 30;
    }

    let mut vaddr_idx = 0;
    while vaddr_idx + 1 < pt_load_vaddr.len() && strtab >= pt_load_vaddr[vaddr_idx + 1] {
        vaddr_idx += 1;
    }

    let strtab_offset = pt_load_offset[vaddr_idx] + strtab - pt_load_vaddr[vaddr_idx];
    let soname_buf_offset = s.string_table.n;

    if soname != u64::MAX {
        if fptr.seek(SeekFrom::Start(strtab_offset + soname)).is_err() {
            s.string_table.n = old_buf_size;
            return 24;
        }
        string_table_copy_from_file(&mut s.string_table, &mut fptr);
    }

    let in_exclude_list = soname != u64::MAX && is_in_exclude_list(&s.string_table.arr[soname_buf_offset..]);
    let should_recurse = depth < s.max_depth as usize
        && ((!seen_before && !in_exclude_list)
            || (!seen_before && in_exclude_list && s.verbosity >= 2)
            || s.verbosity >= 3);

    if !should_recurse {
        let print_name = if soname == u64::MAX || s.path != 0 {
            current_file
        } else {
            std::str::from_utf8(&s.string_table.arr[soname_buf_offset..]).unwrap_or(current_file)
        };

        let bold_color = if in_exclude_list {
            "\x1b[0;35m"
        } else if seen_before {
            "\x1b[0;34m"
        } else {
            "\x1b[1;36m"
        };

        let regular_color = if in_exclude_list {
            "\x1b[0;35m"
        } else if seen_before {
            "\x1b[0;34m"
        } else {
            "\x1b[0;36m"
        };

        let highlight = !seen_before && !in_exclude_list;
        print_line(depth, print_name, bold_color, regular_color, highlight, reason, s);
        s.string_table.n = old_buf_size;
        return 0;
    }

    let mut origin = [0u8; 4096];
    if let Some(last_slash) = current_file.rfind('/') {
        let bytes = last_slash;
        origin[..bytes].copy_from_slice(&current_file.as_bytes()[..bytes]);
    } else {
        origin[..2].copy_from_slice(b"./");
    }

    if rpath == u64::MAX {
        s.rpath_offsets[depth] = usize::MAX;
    } else {
        s.rpath_offsets[depth] = s.string_table.n;
        if fptr.seek(SeekFrom::Start(strtab_offset + rpath)).is_err() {
            s.string_table.n = old_buf_size;
            return 25;
        }
        string_table_copy_from_file(&mut s.string_table, &mut fptr);
        let curr_buf_size = s.string_table.n;
        if interpolate_variables(s, s.rpath_offsets[depth], std::str::from_utf8(&origin).unwrap()).is_err() {
            s.rpath_offsets[depth] = curr_buf_size;
        }
    }

    let runpath_buf_offset = s.string_table.n;
    if runpath != u64::MAX {
        if fptr.seek(SeekFrom::Start(strtab_offset + runpath)).is_err() {
            s.string_table.n = old_buf_size;
            return 26;
        }
        string_table_copy_from_file(&mut s.string_table, &mut fptr);
        let curr_buf_size = s.string_table.n;
        if interpolate_variables(s, runpath_buf_offset, std::str::from_utf8(&origin).unwrap()).is_err() {
            runpath_buf_offset = curr_buf_size;
        }
    }

    let mut needed_buf_offsets = SmallVecU64::new();
    for &needed_offset in &needed {
        needed_buf_offsets.append(s.string_table.n);
        if fptr.seek(SeekFrom::Start(strtab_offset + needed_offset)).is_err() {
            s.string_table.n = old_buf_size;
            return 27;
        }
        string_table_copy_from_file(&mut s.string_table, &mut fptr);
    }

    let print_name = if soname == u64::MAX || s.path != 0 {
        current_file
    } else {
        std::str::from_utf8(&s.string_table.arr[soname_buf_offset..]).unwrap_or(current_file)
    };

    let bold_color = if in_exclude_list {
        "\x1b[0;35m"
    } else if seen_before {
        "\x1b[0;34m"
    } else {
        "\x1b[1;36m"
    };

    let regular_color = if in_exclude_list {
        "\x1b[0;35m"
    } else if seen_before {
        "\x1b[0;34m"
    } else {
        "\x1b[0;36m"
    };

    let highlight = !seen_before && !in_exclude_list;
    print_line(depth, print_name, bold_color, regular_color, highlight, reason, s);

    let mut exit_code = 0;
    let mut needed_not_found = needed_buf_offsets.len();
    if needed_not_found > 0 && s.verbosity == 0 {
        apply_exclude_list(&mut needed_not_found, &mut needed_buf_offsets, s);
    }

    if needed_not_found > 0 {
        exit_code |= check_absolute_paths(&mut needed_not_found, &mut needed_buf_offsets, depth, s, curr_type);
    }

    if runpath == u64::MAX {
        for j in (0..=depth).rev() {
            if needed_not_found == 0 {
                break;
            }
            if s.rpath_offsets[j] == usize::MAX {
                continue;
            }
            exit_code |= check_search_paths(
                Found { how: How::Rpath, depth: j },
                s.rpath_offsets[j],
                &mut needed_not_found,
                &mut needed_buf_offsets,
                depth,
                s,
                curr_type,
            );
        }
    }

    if needed_not_found > 0 && s.ld_library_path_offset != usize::MAX {
        exit_code |= check_search_paths(
            Found { how: How::LdLibraryPath, depth: 0 },
            s.ld_library_path_offset,
            &mut needed_not_found,
            &mut needed_buf_offsets,
            depth,
            s,
            curr_type,
        );
    }

    if needed_not_found > 0 && runpath != u64::MAX {
        exit_code |= check_search_paths(
            Found { how: How::Runpath, depth: 0 },
            runpath_buf_offset,
            &mut needed_not_found,
            &mut needed_buf_offsets,
            depth,
            s,
            curr_type,
        );
    }

    if needed_not_found > 0 && !no_def_lib {
        exit_code |= check_search_paths(
            Found { how: How::LdSoConf, depth: 0 },
            s.ld_so_conf_offset,
            &mut needed_not_found,
            &mut needed_buf_offsets,
            depth,
            s,
            curr_type,
        );
    }

    if needed_not_found > 0 && !no_def_lib {
        exit_code |= check_search_paths(
            Found { how: How::Default, depth: 0 },
            s.default_paths_offset,
            &mut needed_not_found,
            &mut needed_buf_offsets,
            depth,
            s,
            curr_type,
        );
    }

    if needed_not_found > 0 {
        print_error(
            depth,
            needed_not_found,
            &needed_buf_offsets,
            if runpath == u64::MAX {
                None
            } else {
                Some(std::str::from_utf8(&s.string_table.arr[runpath_buf_offset..]).unwrap())
            },
            s,
            no_def_lib,
        );
        s.string_table.n = old_buf_size;
        return 28;
    }

    s.string_table.n = old_buf_size;
    exit_code
}

pub fn check_absolute_paths(
    needed_not_found: &mut usize,
    needed_buf_offsets: &mut SmallVecU64,
    depth: usize,
    s: &mut LibtreeState,
    compat: CompatT,
) -> i32 {
    let mut exit_code = 0;
    let st = &s.string_table;

    let mut i = 0;
    while i < *needed_not_found {
        if st.arr[needed_buf_offsets[i] as usize..].iter().position(|&c| c == b'/').is_none() {
            i += 1;
            continue;
        }

        let path = &st.arr[needed_buf_offsets[i] as usize..];
        let path_str = std::str::from_utf8(path).unwrap_or("");
        if path_str.len() >= 4096 {
            continue;
        }

        s.found_all_needed[depth] = *needed_not_found <= 1;
        let mut err = None;

        if !path_str.starts_with('/') {
            err = Some(" is not absolute");
            exit_code = 28;
        } else {
            let code = recurse(path_str, depth + 1, s, compat, Found { how: How::Direct, depth: 0 });
            if code == 28 {
                exit_code = 28;
            }
            if code != 0 && code != 28 {
                err = Some(" not found");
            }
        }

        if let Some(err_msg) = err {
            tree_preamble(s, depth + 1);
            if s.color != 0 {
                print!("\x1b[1;31m");
            }
            print!("{}{}", path_str, err_msg);
            if s.color != 0 {
                print!("\x1b[0m");
            }
            println!();
        }

        let tmp = needed_buf_offsets[i];
        needed_buf_offsets[i] = needed_buf_offsets[*needed_not_found - 1];
        needed_buf_offsets[*needed_not_found - 1] = tmp;
        *needed_not_found -= 1;
    }

    exit_code
}

pub fn check_search_paths(
    reason: Found,
    offset: usize,
    needed_not_found: &mut usize,
    needed_buf_offsets: &mut SmallVecU64,
    depth: usize,
    s: &mut LibtreeState,
    compat: CompatT,
) -> i32 {
    let mut exit_code = 0;
    let mut path = [0u8; 4096];
    let path_end = path.len();
    let st = &s.string_table;

    let mut offset = offset;
    while st.arr[offset] != 0 {
        while st.arr[offset] == b':' && st.arr[offset] != 0 {
            offset += 1;
        }
        if st.arr[offset] == 0 {
            return exit_code;
        }

        let mut dest = 0;
        while st.arr[offset] != 0 && st.arr[offset] != b':' && dest < path_end {
            path[dest] = st.arr[offset];
            dest += 1;
            offset += 1;
        }

        if dest + 1 >= path_end {
            continue;
        }

        if path[dest - 1] != b'/' {
            path[dest] = b'/';
            dest += 1;
        }

        let search_path_end = dest;
        let mut i = 0;
        while i < *needed_not_found {
            let soname_len = st.arr[needed_buf_offsets[i] as usize..]
                .iter()
                .position(|&c| c == 0)
                .unwrap_or(0);

            if search_path_end + soname_len + 1 >= path_end {
                continue;
            }

            path[search_path_end..search_path_end + soname_len]
                .copy_from_slice(&st.arr[needed_buf_offsets[i] as usize..needed_buf_offsets[i] as usize + soname_len]);
            path[search_path_end + soname_len] = 0;

            s.found_all_needed[depth] = *needed_not_found <= 1;
