use std::env;
use std::ffi::CString;
use std::io::{self, Write};
use std::process;
use std::ptr;
use std::str;
use libc::{isatty, uname, utsname};

pub fn main() -> i32 {
    let mut s = LibtreeState {
        color: (env::var("NO_COLOR").is_err() && unsafe { isatty(1) != 0 }) as i32,
        verbosity: 0,
        path: 0,
        max_depth: 32,
        ld_conf_file: Some(String::from("/etc/ld.so.conf")),
        platform: None,
        lib: Some(String::from("lib")),
        osname: None,
        osrel: None,
        string_table: StringTable::default(),
        visited: VisitedFileArray::default(),
        rpath_offsets: [0; 32],
        ld_library_path_offset: 0,
        default_paths_offset: 0,
        ld_so_conf_offset: 0,
        found_all_needed: [0; 32],
    };

    let mut uname_val = unsafe { std::mem::zeroed::<utsname>() };
    if unsafe { uname(&mut uname_val) } != 0 {
        return 1;
    }

    s.platform = Some(unsafe { CStr::from_ptr(uname_val.machine.as_ptr()) }.to_string_lossy().into_owned());
    s.osname = Some(unsafe { CStr::from_ptr(uname_val.sysname.as_ptr()) }.to_string_lossy().into_owned());
    s.osrel = Some(unsafe { CStr::from_ptr(uname_val.release.as_ptr()) }.to_string_lossy().into_owned());

    if s.osname.as_deref() == Some("FreeBSD") {
        s.ld_conf_file = Some(String::from("/etc/ld-elf.so.conf"));
    }

    let mut opt_help = false;
    let mut opt_version = false;
    let mut opt_raw = false;
    let mut positional = 1;

    let args: Vec<String> = env::args().collect();
    let argc = args.len();
    let mut argv: Vec<&str> = args.iter().map(|s| s.as_str()).collect();

    for i in 1..argc {
        let arg = argv[i];
        if opt_raw || !arg.starts_with('-') || arg.len() == 1 {
            argv[positional] = arg;
            positional += 1;
            continue;
        }

        let mut arg = &arg[1..];
        if arg.starts_with('-') {
            arg = &arg[1..];
            if arg.is_empty() {
                opt_raw = true;
                continue;
            }
            match arg {
                "version" => opt_version = true,
                "path" => s.path = 1,
                "verbose" => s.verbosity += 1,
                "help" => opt_help = true,
                "ldconf" => {
                    if i + 1 == argc {
                        eprintln!("Expected value after `--ldconf`");
                        return 1;
                    }
                    s.ld_conf_file = Some(String::from(argv[i + 1]));
                    i += 1;
                }
                "max-depth" => {
                    if i + 1 == argc {
                        eprintln!("Expected value after `--max-depth`");
                        return 1;
                    }
                    let max_depth = argv[i + 1].parse::<u64>().unwrap_or(32);
                    s.max_depth = max_depth.min(32);
                    i += 1;
                }
                _ => {
                    eprintln!("Unrecognized flag `--{}`", arg);
                    return 1;
                }
            }
            continue;
        }

        for c in arg.chars() {
            match c {
                'h' => opt_help = true,
                'p' => s.path = 1,
                'v' => s.verbosity += 1,
                _ => {
                    eprintln!("Unrecognized flag `-{}`", c);
                    return 1;
                }
            }
        }
    }

    argv.remove(0);
    positional -= 1;

    if opt_help || (!opt_version && positional == 0) {
        println!(
            "Show the dynamic dependency tree of ELF files\n\
            Usage: libtree [OPTION]... [--] FILE [FILES]...\n\
            \n\
            -h, --help     Print help info\n\
            --version      Print version info\n\
            \n\
            File names starting with '-', for example '-.so', can be specified as follows:\n\
            libtree -- -.so\n\
            \n\
            Locating libs options:\n\
            -p, --path       Show the path of libraries instead of the soname\n\
            -v               Show libraries skipped by default*\n\
            -vv              Show dependencies of libraries skipped by default*\n\
            -vvv             Show dependencies of already encountered libraries\n\
            --ldconf <path>  Config file for extra search paths [{}]\n\
            --max-depth <n>  Limit library traversal to at most n levels of depth\n\
            \n\
            * For brevity, the following libraries are not shown by default:\n\
            ",
            s.ld_conf_file.as_deref().unwrap_or("")
        );

        let mut cursor_x = 3;
        for (i, lib) in EXCLUDE_LIST.iter().enumerate() {
            cursor_x += lib.len();
            if cursor_x > 60 {
                cursor_x = 3;
                println!("\n  ");
            }
            print!("{}", lib);
            if i + 1 != EXCLUDE_LIST.len() {
                print!(", ");
            }
        }
        println!(
            ".\n\nThe following rpath/runpath substitutions are used:\n\
            PLATFORM       {}\n\
            LIB            {}\n\
            OSNAME         {}\n\
            OSREL          {}\n",
            s.platform.as_deref().unwrap_or(""),
            s.lib.as_deref().unwrap_or(""),
            s.osname.as_deref().unwrap_or(""),
            s.osrel.as_deref().unwrap_or("")
        );
        return !opt_help as i32;
    }

    if opt_version {
        println!("3.1.1");
        return 0;
    }

    print_tree(positional, argv, &mut s)
}

